    """Persist a normalized incoming record through the repository."""
    return repo.save(record)

def save(self, task: dict) -> dict:
    """Persist a task; missing tasks or identifiers are invalid."""
    if task is None or not task.get("id"):
        raise ValueError("Task requires an id")
    self.connection.execute(task["id"], task)
    return task

def execute(self, key: str, value: dict | None = None) -> dict | None:
    """Read or write a row; reject operations after close."""
    if self.closed:
        raise RuntimeError("Connection is closed")
    if value is not None:
        self.rows[key] = value
    return self.rows.get(key)

